// End-to-end with REAL cryptography: UltraHonk proof generated with bb.js and verified on-chain by the
// SpendVerifier generated by `npm run build:circuits`, inside ShieldedPool.transact.
// Needs Aztec's public CRS (downloaded by bb.js on first use).
const { expect } = require("chai");
const { ethers } = require("hardhat");
const { time } = require("@nomicfoundation/hardhat-network-helpers");
const path = require("path");
const { pathToFileURL } = require("url");

const importEsm = (p) => import(pathToFileURL(path.join(__dirname, "..", p)).href);

describe("ShieldedPool + real SpendVerifier (e2e)", function () {
  this.timeout(900_000);

  it("deposit and withdrawal with real proofs; a tampered proof is rejected on-chain", async function () {
    const [owner, alice, other] = await ethers.getSigners();
    const sdk = await importEsm("sdk/aegis.mjs");
    const helpers = await importEsm("noir_circuits/test/helpers.mjs");
    const { Barretenberg, UltraHonkBackend } = await import("@aztec/bb.js");
    const aegis = await sdk.Aegis.create();
    const tax = await aegis.auditorKeypair();
    const aml = await aegis.auditorKeypair();
    const ISSUER = helpers.ISSUER_KEY;
    const TIER_LIMITS = [0n, 100_000_000n, 1_500_000_000n, 10n ** 14n];

    const token = await (await ethers.getContractFactory("MockERC20")).deploy();
    const { deployHonkVerifier } = require("../scripts/lib/deploy_verifier");
    const verifier = await deployHonkVerifier(ethers, "SpendVerifier");
    const pool = await (await ethers.getContractFactory("ShieldedPool")).deploy(
      await token.getAddress(), await verifier.getAddress(), owner.address, 0b11n, TIER_LIMITS,
      { x: tax.pub.x, y: tax.pub.y }, { x: aml.pub.x, y: aml.pub.y }, 10_000_000_000n, 1_000_000_000n,
    );
    const issuer = sdk.Aegis.issuerPublicKey(ISSUER);
    await pool.setIssuer(issuer.x, issuer.y, true);
    await token.mint(alice.address, 1_000_000_000n);
    await token.connect(alice).approve(await pool.getAddress(), ethers.MaxUint256);

    const program = await helpers.loadCircuit("spend");
    const api = await Barretenberg.new({ threads: 4 });
    const backend = new UltraHonkBackend(program.bytecode, api);
    const tree = await sdk.MerkleTree.create(aegis);
    const secret = sdk.randomField();
    const me = await aegis.ownerPubkey(secret);
    let slot = 0;

    async function prove({ inputs = [], outputs, publicIn = 0n, publicOut = 0n, ext }) {
      const now = BigInt(await time.latest());
      const credential = await aegis.issueCredential(ISSUER, me, { tier: 2, jurisdiction: 0, expiry: now + 86_400n, personTag: 42n });
      const extData = { recipient: ext?.recipient ?? ethers.ZeroAddress, relayer: ethers.ZeroAddress, fee: 0n,
        encryptedOutput0: "0x01", encryptedOutput1: "0x02" };
      const { inputs: w } = await helpers.buildSpend(aegis, tree, {
        secret, asset: BigInt(await token.getAddress()), credential, taxKey: tax.pub, amlKey: aml.pub,
        inputs, outputs, publicIn, publicOut, extDataHash: await pool.extDataHash(extData), rateSlot: slot++,
      }, { now, allowed: 0b11n });
      w.tier_limits = TIER_LIMITS.map(String);
      const { witness, returnValue } = await helpers.execute("spend", w);
      const proof = await backend.generateProof(witness, { verifierTarget: "evm" });
      const [te, tc, ae, ac, rn] = returnValue;
      return {
        w, extData,
        p: { proof: ethers.hexlify(proof.proof), root: w.root, nullifiers: w.nullifiers, outCommitments: w.out_commitments,
          publicIn, publicOut, timestamp: now, issuer: { x: issuer.x, y: issuer.y },
          taxEph: { x: te.x, y: te.y }, taxCt: tc, amlEph: { x: ae.x, y: ae.y }, amlCt: ac, rateNullifier: rn },
      };
    }

    // 1. Deposit of 500 EURC with a real proof
    const b0 = sdk.randomField();
    const dep = await prove({ publicIn: 500_000_000n,
      outputs: [{ amount: 500_000_000n, owner: me, blinding: b0 }, { amount: 0n, owner: me, blinding: sdk.randomField() }] });
    const rcpt = await (await pool.connect(alice).transact(dep.p, dep.extData)).wait();
    console.log(`      gas deposit with on-chain verification: ${rcpt.gasUsed}`);
    tree.insert(BigInt(dep.w.out_commitments[0]));
    tree.insert(BigInt(dep.w.out_commitments[1]));

    // 2. Withdrawal of 120 EURC to `other`
    const wd = await prove({ publicOut: 120_000_000n, inputs: [{ amount: 500_000_000n, blinding: b0, leafIndex: 0 }],
      outputs: [{ amount: 0n, owner: me, blinding: sdk.randomField() }, { amount: 380_000_000n, owner: me, blinding: sdk.randomField() }],
      ext: { recipient: other.address } });

    // a front-runner who changes the recipient: the same proof no longer verifies on-chain
    const stolen = { ...wd.extData, recipient: owner.address };
    await expect(pool.connect(owner).transact(wd.p, stolen)).to.be.reverted;

    const r2 = await (await pool.connect(other).transact(wd.p, wd.extData)).wait();
    console.log(`      gas withdrawal with on-chain verification: ${r2.gasUsed}`);
    expect(await token.balanceOf(other.address)).to.equal(120_000_000n);
    await api.destroy();
    await aegis.destroy();
  });
});
